<#
=====================================================================
 ABFverify - Gift Sending feature installer
 --------------------------------------------------------------------
 WHAT IT DOES
   1. Creates the new "gifts" Django app (models, views, admin,
      services, urls, context processor, migration 0001).
   2. Adds the customer pages: Send a Gift + My Gift Orders.
   3. Adds the finance-side Gift Orders page + glowing bell on all
      finance pages.
   4. Patches settings.py, config/urls.py, finance/views.py,
      finance/urls.py, finance.css, dashboard_base.html and the 4
      finance templates (a .bak-gifts backup is kept for each).
   5. Runs migrations + collectstatic.

 HOW TO RUN (from the project root, next to manage.py):
   powershell -ExecutionPolicy Bypass -File .\install_gifts.ps1
=====================================================================
#>

$ErrorActionPreference = "Stop"

# ---------- locate project root ----------
$root = Get-Location
if (-not (Test-Path (Join-Path $root "manage.py"))) {
    Write-Host "ERROR: manage.py not found." -ForegroundColor Red
    Write-Host "cd into your project root (next to manage.py) and run again." -ForegroundColor Yellow
    exit 1
}
Write-Host "Project root: $root" -ForegroundColor Cyan

function Read-Utf8([string]$path) {
    return [IO.File]::ReadAllText($path, (New-Object Text.UTF8Encoding($false)))
}
function Write-Utf8([string]$path, [string]$content) {
    [IO.File]::WriteAllText($path, $content, (New-Object Text.UTF8Encoding($false)))
}
function Backup-Once([string]$path) {
    $bak = "$path.bak-gifts"
    if ((Test-Path $path) -and -not (Test-Path $bak)) {
        Copy-Item $path $bak
        Write-Host "  backup -> $bak" -ForegroundColor DarkGray
    }
}
function Write-B64File([string]$rel, [string]$b64) {
    $dest = Join-Path $root $rel
    $dir = Split-Path $dest -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    [IO.File]::WriteAllBytes($dest, [Convert]::FromBase64String($b64))
    Write-Host "  wrote $rel" -ForegroundColor DarkGray
}

# ---------- payload files (base64) ----------
$payload = @{}
$payload["gifts/__init__.py"] = ""
$payload["gifts/apps.py"] = "ZnJvbSBkamFuZ28uYXBwcyBpbXBvcnQgQXBwQ29uZmlnCgoKY2xhc3MgR2lmdHNDb25maWcoQXBwQ29uZmlnKToKICAgIGRlZmF1bHRfYXV0b19maWVsZCA9ICJkamFuZ28uZGIubW9kZWxzLkJpZ0F1dG9GaWVsZCIKICAgIG5hbWUgPSAiZ2lmdHMiCg=="
$payload["gifts/admin.py"] = ""
$payload["gifts/models.py"] = ""
$payload["gifts/services.py"] = ""
$payload["gifts/views.py"] = ""
$payload["gifts/urls.py"] = ""
$payload["gifts/context_processors.py"] = ""
$payload["gifts/migrations/__init__.py"] = ""
$payload["gifts/migrations/0001_initial.py"] = ""
$payload["templates/panel/gift_sending.html"] = ""
$payload["templates/panel/my_gift_orders.html"] = ""
$payload["templates/finance/includes/gift_bell.html"] = ""
$payload["templates/finance/gift_orders.html"] = ""
$payload["static/css/gifts.css"] = ""
$payload["static/js/gifts.js"] = ""
$payload["static/js/gift_orders.js"] = ""
$VIEWS_APPEND_B64 = ""
$CSS_APPEND_B64 = ""
$SIDEBAR_B64 = ""
$URLS_INSERT_B64 = ""
$BELL_INCLUDE_B64 = "PGRpdiBjbGFzcz0iaGVhZGVyLWFjdGlvbnMiPgogICAgICAgIHslIGluY2x1ZGUgImZpbmFuY2UvaW5jbHVkZXMvZ2lmdF9iZWxsLmh0bWwiICV9"

# ---------- 1) write payload files ----------
Write-Host "`n[1/7] Writing gifts app, templates and static files..." -ForegroundColor Green
foreach ($rel in $payload.Keys) {
    Write-B64File $rel $payload[$rel]
}

function Decode([string]$b64) {
    return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64))
}

# ---------- 2) patch config/settings.py ----------
Write-Host "`n[2/7] Patching config/settings.py..." -ForegroundColor Green
$settingsPath = Join-Path $root "config\settings.py"
Backup-Once $settingsPath
$s = Read-Utf8 $settingsPath

if ($s -notmatch '"gifts",') {
    $anchor = '    "referrals",'
    if ($s.Contains($anchor)) {
        $s = $s.Replace($anchor, $anchor + "`r`n" + '    "gifts",')
        Write-Host "  added gifts to INSTALLED_APPS" -ForegroundColor DarkGray
    } else {
        Write-Host "  WARNING: could not find `"referrals`", in INSTALLED_APPS - add `"gifts`", manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  INSTALLED_APPS already patched, skipping" -ForegroundColor DarkGray
}

if ($s -notmatch 'gifts\.context_processors\.pending_gift_orders') {
    $cpAnchor = '"wallet.context_processors.wallet_balance",'
    if ($s.Contains($cpAnchor)) {
        $s = $s.Replace($cpAnchor, $cpAnchor + "`r`n" + '                "gifts.context_processors.pending_gift_orders",')
        Write-Host "  added gift orders context processor" -ForegroundColor DarkGray
    } else {
        Write-Host "  WARNING: wallet context processor line not found - add gifts.context_processors.pending_gift_orders manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  context processor already patched, skipping" -ForegroundColor DarkGray
}
Write-Utf8 $settingsPath $s

# ---------- 3) patch config/urls.py ----------
Write-Host "`n[3/7] Patching config/urls.py..." -ForegroundColor Green
$urlsPath = Join-Path $root "config\urls.py"
Backup-Once $urlsPath
$u = Read-Utf8 $urlsPath
if ($u -notmatch 'include\("gifts\.urls"\)') {
    $anchor = '    path("", include("marketplace.urls")),'
    if ($u.Contains($anchor)) {
        $u = $u.Replace($anchor, $anchor + "`r`n`r`n    path(`"`", include(`"gifts.urls`")),")
        Write-Host "  added gifts urls" -ForegroundColor DarkGray
    } else {
        Write-Host "  WARNING: marketplace include not found - add path(`"`", include(`"gifts.urls`")) manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  urls already patched, skipping" -ForegroundColor DarkGray
}
Write-Utf8 $urlsPath $u

# ---------- 4) patch finance/views.py + finance/urls.py ----------
Write-Host "`n[4/7] Patching finance views and urls..." -ForegroundColor Green
$fviewsPath = Join-Path $root "finance\views.py"
Backup-Once $fviewsPath
$fv = Read-Utf8 $fviewsPath
if ($fv -notmatch 'def gift_orders\(') {
    if (-not $fv.EndsWith("`n")) { $fv += "`r`n" }
    $fv += (Decode $VIEWS_APPEND_B64).Replace("`n", "`r`n")
    Write-Utf8 $fviewsPath $fv
    Write-Host "  appended gift_orders + gift_order_update views" -ForegroundColor DarkGray
} else {
    Write-Host "  finance views already patched, skipping" -ForegroundColor DarkGray
}

$furlsPath = Join-Path $root "finance\urls.py"
Backup-Once $furlsPath
$fu = Read-Utf8 $furlsPath
if ($fu -notmatch 'finance_gift_orders') {
    $restockLine = '    path("record-restock/", views.record_untracked_restock, name="record_untracked_restock"),'
    if ($fu.Contains($restockLine)) {
        $fu = $fu.Replace($restockLine, (Decode $URLS_INSERT_B64).Replace("`n", "`r`n"))
        Write-Utf8 $furlsPath $fu
        Write-Host "  added gift order routes" -ForegroundColor DarkGray
    } else {
        Write-Host "  WARNING: record-restock route not found - add the gift-orders routes to finance/urls.py manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  finance urls already patched, skipping" -ForegroundColor DarkGray
}

# ---------- 5) append finance.css ----------
Write-Host "`n[5/7] Appending gift styles to static/css/finance.css..." -ForegroundColor Green
$fcssPath = Join-Path $root "static\css\finance.css"
Backup-Once $fcssPath
$fc = Read-Utf8 $fcssPath
if ($fc -notmatch 'gift-bell') {
    if (-not $fc.EndsWith("`n")) { $fc += "`r`n" }
    $fc += (Decode $CSS_APPEND_B64).Replace("`n", "`r`n")
    Write-Utf8 $fcssPath $fc
    Write-Host "  appended bell + gift orders styles" -ForegroundColor DarkGray
} else {
    Write-Host "  finance.css already patched, skipping" -ForegroundColor DarkGray
}

# ---------- 6) patch dashboard_base.html sidebar + finance page bells ----------
Write-Host "`n[6/7] Patching sidebar and finance page bells..." -ForegroundColor Green
$basePath = Join-Path $root "templates\panel\dashboard_base.html"
Backup-Once $basePath
$bt = Read-Utf8 $basePath
if ($bt -notmatch 'fa-gifts') {
    $rocketIdx = $bt.IndexOf('fa-rocket')
    if ($rocketIdx -ge 0) {
        $closeIdx = $bt.IndexOf('</button>', $rocketIdx)
        if ($closeIdx -ge 0) {
            $insertAt = $closeIdx + '</button>'.Length
            $sidebar = (Decode $SIDEBAR_B64).Replace("`n", "`r`n")
            $bt = $bt.Substring(0, $insertAt) + $sidebar + $bt.Substring($insertAt)
            Write-Utf8 $basePath $bt
            Write-Host "  added Send Gift + My Gift Orders to sidebar" -ForegroundColor DarkGray
        } else {
            Write-Host "  WARNING: closing </button> after Boost not found." -ForegroundColor Yellow
        }
    } else {
        Write-Host "  WARNING: Boost Accounts button not found - add the sidebar buttons manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  sidebar already patched, skipping" -ForegroundColor DarkGray
}

$financeTemplates = @(
    "templates\finance\dashboard.html",
    "templates\finance\analytics.html",
    "templates\finance\inventory.html",
    "templates\finance\rewards.html"
)
$bellLine = (Decode $BELL_INCLUDE_B64).Replace("`n", "`r`n")
foreach ($rel in $financeTemplates) {
    $p = Join-Path $root $rel
    if (-not (Test-Path $p)) {
        Write-Host "  WARNING: $rel not found, skipping" -ForegroundColor Yellow
        continue
    }
    Backup-Once $p
    $c = Read-Utf8 $p
    if ($c -notmatch 'gift_bell\.html') {
        $ha = '<div class="header-actions">'
        if ($c.Contains($ha)) {
            $c = $c.Replace($ha, $bellLine)   # .Replace replaces ALL, header-actions appears once per page
            Write-Utf8 $p $c
            Write-Host "  bell added to $rel" -ForegroundColor DarkGray
        } else {
            Write-Host "  WARNING: header-actions not found in $rel" -ForegroundColor Yellow
        }
    } else {
        Write-Host "  $rel already has the bell, skipping" -ForegroundColor DarkGray
    }
}

# ---------- 7) Django: check + migrate + collectstatic ----------
Write-Host "`n[7/7] Running Django checks and migrations..." -ForegroundColor Green

$py = "python"
try { & $py --version | Out-Null } catch {
    Write-Host "WARNING: 'python' not found on PATH - run these manually:" -ForegroundColor Yellow
    Write-Host "  python manage.py migrate" -ForegroundColor Yellow
    Write-Host "  python manage.py collectstatic --noinput" -ForegroundColor Yellow
    $py = $null
}

if ($py) {
    & $py manage.py check
    if ($LASTEXITCODE -ne 0) {
        Write-Host "ERROR: 'manage.py check' failed - fix the error above, then run migrate." -ForegroundColor Red
        exit 1
    }
    & $py manage.py migrate
    if ($LASTEXITCODE -ne 0) {
        Write-Host "ERROR: migrations failed - see the message above." -ForegroundColor Red
        exit 1
    }
    & $py manage.py collectstatic --noinput
    if ($LASTEXITCODE -ne 0) {
        Write-Host "NOTE: collectstatic failed locally - not fatal. Run it on your server during deploy." -ForegroundColor Yellow
    }
}

Write-Host ""
Write-Host "==================================================================" -ForegroundColor Green
Write-Host " GIFT SENDING INSTALLED SUCCESSFULLY" -ForegroundColor Green
Write-Host "==================================================================" -ForegroundColor Green
Write-Host ""
Write-Host "Next steps:" -ForegroundColor Cyan
Write-Host "  1. Commit + push your code, then on the server run:"
Write-Host "       python manage.py migrate"
Write-Host "       python manage.py collectstatic --noinput"
Write-Host "  2. In the Django admin (/semilore/) under 'Gifts':"
Write-Host "       - create Gift Categories (e.g. Flowers, Frames)"
Write-Host "       - create Gift Groups with picture, price and delivery duration"
Write-Host "  3. Customer pages:  sidebar -> 'Send Gift' and 'My Gift Orders'"
Write-Host "  4. Finance pages:   the glowing bell (top right) -> Gift Orders"
Write-Host ""
Write-Host "Backups of every patched file were saved as .bak-gifts next to the original." -ForegroundColor DarkGray
